-- Related design concepts; only seed unmigrated rows. An empty array intentionally means no supporting images.
update sf_product set supporting_images = case when image_url = '/images/xj-wardrobe-2.jpg' then '["/images/xj-wardrobe-v2.jpg","/images/xj-wardrobe-3.jpg"]' when image_url = '/images/xj-wardrobe-3.jpg' then '["/images/xj-wardrobe-2.jpg","/images/xj-wardrobe-v2.jpg"]' else '["/images/xj-wardrobe-2.jpg","/images/xj-wardrobe-3.jpg"]' end where category = 'wardrobes' and supporting_images is null;
update sf_product set supporting_images = case when image_url = '/images/xj-living-2.jpg' then '["/images/xj-living-v2.jpg","/images/xj-living-3.jpg"]' when image_url = '/images/xj-living-3.jpg' then '["/images/xj-living-2.jpg","/images/xj-living-v2.jpg"]' else '["/images/xj-living-2.jpg","/images/xj-living-3.jpg"]' end where category = 'living' and supporting_images is null;
