update sf_product set supporting_images = case when image_url = '/images/xj-bathroom-2.jpg' then '["/images/xj-bathroom-v2.jpg","/images/xj-bathroom-3.jpg"]' when image_url = '/images/xj-bathroom-3.jpg' then '["/images/xj-bathroom-2.jpg","/images/xj-bathroom-v2.jpg"]' else '["/images/xj-bathroom-2.jpg","/images/xj-bathroom-3.jpg"]' end where category = 'bathroom' and supporting_images is null;
update sf_product set supporting_images = case when image_url = '/images/xj-outdoor-2.jpg' then '["/images/xj-outdoor-v2.jpg","/images/xj-outdoor-3.jpg"]' when image_url = '/images/xj-outdoor-3.jpg' then '["/images/xj-outdoor-2.jpg","/images/xj-outdoor-v2.jpg"]' else '["/images/xj-outdoor-2.jpg","/images/xj-outdoor-3.jpg"]' end where category = 'outdoor' and supporting_images is null;
